contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 assertionId, bool truthfully) public {
        address asserter = address(c.optimisticAsserter());
        bool r1;
        bool r2;
        if (asserter == address(this)) {
            try c.assertionResolvedCallback(assertionId, truthfully) { r1 = false; } catch { r1 = true; }
            try c.assertionDisputedCallback(assertionId) { r2 = false; } catch { r2 = true; }
            assert(!r1 && !r2);
        } else {
            try c.assertionResolvedCallback(assertionId, truthfully) { r1 = false; } catch { r1 = true; }
            try c.assertionDisputedCallback(assertionId) { r2 = false; } catch { r2 = true; }
            assert(r1 && r2);
        }
    }
    receive() external payable {}
}

