contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 assertionId, address disputeCaller, bytes32 identifier, uint256 time, uint256 amount) public payable {
        require(address(this).balance >= amount);
        // decide whether to (attempt to) hold Ether; c must never gain any of it
        uint256 balBefore = address(c).balance;
        // view call: must succeed and return true for ANY caller
        bool allowed = c.isDisputeAllowed(assertionId, disputeCaller);
        // state-changing call: this contract is not the optimistic asserter, so it must revert
        bool reverted;
        try c.requestPrice(identifier, time, "") {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(allowed && reverted && address(c).balance == balBefore && address(c).balance == 0);
    }

    receive() external payable {}
}

